package com.bank.portfolio.service;

import java.util.logging.Logger;

// Counts contiguous stretches whose product of positive multipliers is below a threshold.
public class GrowthWindowCounter {
    private static final Logger log = Logger.getLogger(GrowthWindowCounter.class.getName());

    public long countSafeStretches(int[] multipliers, int threshold) {
        if (multipliers == null || threshold <= 1) {
            log.warning("Threshold <= 1 means no stretch can qualify.");
            return 0L;
        }
        long product = 1L;
        int left = 0;
        long count = 0L;

        for (int right = 0; right < multipliers.length; right++) {
            product *= multipliers[right];        // expand window on the right
            while (product >= threshold && left <= right) {
                product /= multipliers[left];     // shrink window from the left
                left++;
            }
            count += (right - left + 1);          // all subarrays ending at right
        }
        final long total = count;
        log.info(() -> "Safe stretches below " + threshold + " = " + total);
        return count;
    }
}
