package com.bank.portfolio;

import com.bank.portfolio.service.GrowthWindowCounter;
import java.util.logging.Logger;

public class GrowthWindowDemo {
    private static final Logger log = Logger.getLogger(GrowthWindowDemo.class.getName());

    public static void main(String[] args) {
        // Positive daily growth multipliers and a risk threshold.
        int[] multipliers = {10, 5, 2, 6};
        int threshold = 100;

        GrowthWindowCounter counter = new GrowthWindowCounter();
        long safe = counter.countSafeStretches(multipliers, threshold);

        log.info(() -> "Number of safe compounding stretches = " + safe);
    }
}
